final_design:
module TopModule (
    input  logic clk,
    input  logic a,
    input  logic b,
    output logic out_assign,
    output logic out_always_comb,
    output logic out_always_ff
);

  // 1. Assign statement XOR
  assign out_assign = a ^ b;

  // 2. Combinational always block XOR
  always_comb begin
    out_always_comb = a ^ b;
  end

  // 3. Clocked always block XOR (sequential, delayed by 1 cycle)
  always_ff @(posedge clk) begin
    out_always_ff <= a ^ b;
  end

endmodule

